-- Pantheons of the Megaverse: the gods' own weapons and items
-- 135 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~119-pantheons-god-weapons.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('tezcatlipoca-sword', 'Tezcatlipoca''s Sword', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The weapon of the Aztec god Tezcatlipoca: called a sword, it is really a club edged with obsidian blades. It is enchanted and indestructible, does 2D6x10 M.D. per strike, and can parry long-range energy attacks at no penalty.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.20', NULL),
  ('xiuhcoatl-turquoise-snake', 'The Xiuhcoatl (Turquoise Snake)', 'rifts', 'weapon', NULL, NULL, NULL, '3D6x10 M.D. as a club; 1D6x10 M.D. flame stream', 1, '1000 ft (305 m) for the flame stream', NULL, NULL, NULL, NULL, NULL, 'The snake-shaped club of the Aztec sun and war god Huitzilopochtli. It does 3D6x10 M.D. as a club, and the snake''s head can shoot a stream of flames for 1D6x10 M.D. out to 1000 ft (305 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.23', NULL),
  ('huitzilopochtli-shield', 'Huitzilopochtli''s Shield', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D. thrown', 1, '1000 ft (305 m) thrown', NULL, NULL, NULL, NULL, NULL, 'The small round shield of the Aztec god Huitzilopochtli. It is indestructible and gives him +3 to parry. It can also be thrown 1000 ft (305 m) for 6D6 M.D., and it returns to the god.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.23', NULL),
  ('huitzilopochtli-hummingbird-feather-armor', 'Huitzilopochtli''s Hummingbird Feather Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'The armor of the Aztec god Huitzilopochtli, made with enchanted hummingbird feathers. It has 1000 M.D.C.; the book prints nothing else for it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.23', NULL),
  ('xipe-totec-enchanted-obsidian-knife', 'Xipe Totec''s Enchanted Obsidian Knife', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 S.D.C. or 6D6+6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The enchanted obsidian knife the Aztec god Xipe Totec uses for torture and sacrifices. On his instruction it does either 6D6 S.D.C. (against normal mortals) or 6D6+6 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.26', NULL),
  ('sword-of-the-sky', 'Sword of the Sky', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.; lightning bolt 1D6x10 M.D.', 1, '2,000 feet (610 m) for the lightning bolt', NULL, NULL, NULL, NULL, NULL, 'The rune sword of the Babylonian god Enlil, which Apsu took from a dead god of another dimension. It is black and indestructible, has I.Q. 11, a telepathic link with Enlil and a scrupulous alignment, and burns any evil being who touches it for 1D4x10 M.D. It does 2D4x10 M.D., double to supernatural intelligences and vampires, and throws a lightning bolt for 1D6x10 M.D. to 2,000 feet (610 m). It casts rain dance, summon storm, drought, hurricane and part waters, each up to six times per 24 hours, as a 10th level water warlock.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.42', NULL),
  ('scepter-of-power', 'Scepter of Power', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The greatest rune weapon of Marduk, lord of the Babylonian gods: a silver rod with an emerald-eyed dragon curled around its head. It is indestructible, has I.Q. 15, a telepathic link to Marduk and a principled alignment, and does 1D4x10 points of damage to any evil creature touching it, again each melee it is held. It does 2D4x10 M.D. as a weapon. It casts calm storm, summon storm, close rift, banishment and rain dance three times each per 24 hours as a 10th level sorcerer, and striking a nexus point with it starts a ley line storm lasting 2D4 minutes that does not harm the wielder.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.43-44', NULL),
  ('spear-of-lightning', 'Spear of Lightning', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.; call lightning 1D4x10 M.D.', 1, '1000 feet (305 m) thrown', NULL, NULL, NULL, NULL, NULL, 'A magic spear of the Babylonian god Marduk: seven feet (2.1 m) long and made of a single silvery piece of solid metal. It does 1D6x10 M.D. It can call lightning as the spell, but for 1D4x10 M.D., which counts as one melee attack. It can be thrown 1000 feet (305 m) and returns magically to the wielder.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.44', NULL),
  ('marduk-net', 'Marduk''s Net', 'rifts', 'weapon', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic net of the Babylonian god Marduk, the one he trapped Tiamat with. Anyone it hits is entangled: he loses three melee attacks per round and is -4 on all combat bonuses, and needs 2D4 melee actions to untangle himself. It holds anyone with a P.S. of 60 or less; stronger creatures escape in half the time. It also gives -60% to any attempt to teleport or dimensional teleport.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.44', NULL),
  ('marduk-bow', 'Marduk''s Bow', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, '4000 feet (1200 m)', NULL, NULL, NULL, NULL, NULL, 'The magic bow of the Babylonian god Marduk, with supernatural range and damage. Its arrows do 1D6x10 M.D. out to 4000 feet (1200 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.44', NULL),
  ('tablets-of-destiny', 'The Tablets of Destiny', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Relics older than Apsu and Tiamat, held by the Babylonian god Marduk. A mortal who owns them becomes an M.D.C. creature (hit points and S.D.C. doubled, then converted to M.D.C.) and is +1 to save vs magic; a supernatural creature has its M.D.C. doubled; a being with godlike powers gains 20,000 M.D.C. The owner also knows all languages, lost and ancient ones included, can understand the workings of any magic or device he examines, and gets glimpses of significant future events.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.44', NULL),
  ('sword-of-victory', 'Sword of Victory', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The greatest rune weapon of the Babylonian goddess Ishtar: a dark red sword whose hilt is two linked dragons, their heads ending in the hand-guard. It has I.Q. 12, a telepathic link with Ishtar and an anarchist alignment, and does 1D4x10 points of damage to any evil creature touching it, every melee it is held. It does 2D6x10 M.D., double to dragons, vampires, demons and Splugorth.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.46', NULL),
  ('spear-of-vengeance', 'Spear of Vengeance', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, '2000 feet (610 m) thrown', NULL, NULL, NULL, NULL, NULL, 'The long, golden-tipped magic spear of the Babylonian goddess Ishtar. It does 2D4x10 M.D., and can be thrown 2000 feet (610 m), returning magically to its owner.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.46', NULL),
  ('ishtar-magical-scale-armor', 'Ishtar''s Magical Scale Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'The magic scale armor of the Babylonian goddess Ishtar. It has 1,000 M.D.C. and is weightless.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.46', NULL),
  ('mummu-techno-wizard-samas-armor', 'Mummu''s Techno-Wizard SAMAS Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 750, 'The Babylonian craftsman god Mummu keeps a pair of captured SAMAS power armor suits, repainted red with gold trim, with techno-wizard modifications and enchantments that tripled their original M.D.C.: the main body is 750 M.D.C., the only location the book prints. The techno-wizard spells built in are Armor of Ithan, invulnerability, chameleon, invisibility and impervious to energy, all at 10th level.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.51', NULL),
  ('mummu-techno-wizard-rail-gun', 'Mummu''s Techno-Wizard Rail Gun', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D. per burst', 1, NULL, '20 bursts', NULL, NULL, NULL, NULL, 'The rail gun of the Babylonian god Mummu: a super-powerful variant of the TK-Machinegun (Rifts RPG, page 92). It does 2D4x10 M.D. per burst and holds 20 bursts; a telekinesis spell or 20 I.S.P. recharges four bursts. Its range is given only as the same as the SAMAS rail gun, with no figure. The modification would cost a normal techno-wizard 1,600 P.P.E.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.51', NULL),
  ('nergal-crimson-bladed-magic-sword', 'Nergal''s Crimson-Bladed Magic Sword', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic sword of the Babylonian god Nergal, with a crimson blade. It is indestructible and does 4D6 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.54', NULL),
  ('nergal-red-magic-scale-armor', 'Nergal''s Red Magic Scale Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'The red magic scale armor of the Babylonian god Nergal. It has 1000 M.D.C. and is weightless.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.54', NULL),
  ('sword-of-gilgamesh', 'Sword of Gilgamesh', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A plain-looking short sword that is really a greatest rune weapon, carried by the demigod king Gilgamesh. It is blue-grey and indestructible, has I.Q. 13, a telepathic link to Gilgamesh and an anarchist alignment, and does 1D6x10 M.D., doubled against dragons and vampires. Its dimension-travelling powers are teleport lesser, teleport greater, mystic portal, time hole, sanctum and dimensional portal, each up to four times per 24 hours except dimensional portal, which is once per day, all as a 10th level spell.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.56', NULL),
  ('gilgamesh-enchanted-scale-armor', 'Gilgamesh''s Enchanted Scale Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'The enchanted scale armor of the demigod king Gilgamesh, a gift of the gods. It has 1,000 M.D.C. and regenerates M.D.C. at 50 per day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.56', NULL),
  ('ea-enchanted-sword', 'Ea''s Enchanted Sword', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The enchanted sword of Ea, the altered Sowki Erghoul who leads the Dark Council of impostor Babylonian gods. It does 6D6 M.D. and is indestructible.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.59', NULL),
  ('enlil-bio-borg-warlock-lesser-rune-sword', 'Enlil the Bio-borg Warlock''s Lesser Rune Sword', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The lesser rune weapon of Krellon the Magnificent, the warlock who poses as the god Enlil. It is a sword with I.Q. 10 and a telepathic link to its owner, and does 4D6 M.D., doubled against creatures of magic, dragons, faeries and gods included.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.61', NULL),
  ('enlil-bio-borg-warlock-ppe-talisman', 'Enlil the Bio-borg Warlock''s P.P.E. Talisman', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A talisman worn by Krellon the Magnificent, the warlock who poses as the god Enlil. It holds 400 P.P.E. and recharges at 10 P.P.E. per hour, doubled at a ley line nexus.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.61', NULL),
  ('enlil-bio-borg-warlock-tw-sunaj-assassin-armor', 'Enlil the Bio-borg Warlock''s TW Modified Sunaj Assassin Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 110, 'Techno-wizard modified Sunaj Assassin armor worn by Krellon the Magnificent, the warlock who poses as the god Enlil. It is repainted bright purple, with the face plate reshaped as a bearded man, and has 110 M.D.C. It is enchanted with the Armor of Ithan spell at 12th level (120 M.D.C.), usable six times a day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.61', NULL),
  ('flameblade', 'Flameblade', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D. psi-sword; psi bolts 6D6 M.D.', 1, '1000 feet (305 m) for the psi bolts', NULL, NULL, NULL, NULL, NULL, 'The rare rune weapon of Gilgamesh the Wanderer: a bladeless handle until activated, when a fiery-looking psi-sword appears from it. It has I.Q. 14, a telepathic link and a scrupulous alignment. The psi-sword does 1D6x10 M.D., and it can shoot psi bolts for 6D6 M.D. up to 1000 feet (305 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.63', NULL),
  ('gilgamesh-the-wanderer-enchanted-scale-mail', 'Gilgamesh the Wanderer''s Enchanted Scale Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1500, 'The enchanted scale mail of Gilgamesh the Wanderer, the ancient armor he found in his pack. It has 1500 M.D.C. and is weightless.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.63', NULL),
  ('zeus-aegis', 'The Aegis', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The shield of Zeus, king of the Greek gods. It is indestructible, and any being who sees its face must save against a Horror Factor of 16 or flee.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.68', NULL),
  ('zeus-bolts-of-the-cyclops', 'The Bolts of the Cyclops', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D. or 3D6x10 M.D.', 1, '2000 ft (610 m)', NULL, NULL, NULL, NULL, NULL, 'Magic lightning bolts forged by Zeus'' cyclops servants, which he carries into battle in place of his weaker natural lightning. A bolt does either 2D6x10 M.D. or 3D6x10 M.D. at a range of 2000 ft (610 m). Zeus sometimes hands 3D4 of them to other gods, priests and heroes as a reward for service.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.68', NULL),
  ('herakles-bow-of-herakles', 'The Bow of Herakles', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D. for Herakles; 2D6 M.D. for anyone else', 1, '2000 ft (610 m) for Herakles; 1200 ft (366 m) for anyone else', NULL, NULL, NULL, NULL, NULL, 'The indestructible holy bow of Herakles; drawing it takes a Strength of at least 24, and only Herakles can use all of its powers. For anyone else it does 2D6 M.D. at double the typical range, 1200 ft (366 m). For Herakles it does 1D4x10 M.D. at 2000 ft (610 m), and triple damage to demons, vampires and alien intelligences.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.69', NULL),
  ('herakles-fur-of-the-nemean-lion', 'The Fur of the Nemean Lion', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The indestructible skin of the Nemean Lion, which Herakles strangled and now wears as armor. Sharp weapon attacks, swords and arrows included, do no damage through it and energy attacks do half damage. Blunt and kinetic attacks, punches, kicks, falls and explosive impact do full damage.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.69', NULL),
  ('hades-helmet-of-invisibility', 'Hades'' Helmet of Invisibility', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The helmet of Hades, Greek god of the underworld. It makes the wearer totally invisible, even to beings that can normally see the invisible. The effect can be kept up for only two hours each day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.72', NULL),
  ('hades-magical-plate-armor', 'Hades'' Magical Plate Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'The magical plate armor of Hades, Greek god of the underworld. The book prints its M.D.C. alone: 2,000.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.72', NULL),
  ('hades-impaler-rune-sword', 'Hades'' Impaler Rune Sword', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.; spikes 2D4+2 M.D. each, all four 1D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Hades'' greatest rune weapon, a drinker of souls and life essences that does 1D6x10 M.D. with physical blows. Four spiked, finger-like appendages can shoot out to impale: one or more can be fired as often as twice per melee round at +2 to strike, 2D4+2 M.D. each, or 1D4x10 M.D. for all four at one target. The sword can also animate and crawl along floors and up walls on its spikes like a spider: speed 12, climbing 80%, two attacks per melee or four non-combat actions.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.72', NULL),
  ('charons-rod', 'Charon''s Rod', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The plain wooden staff Charon, ferryman of the River Styx, uses to push and steer his boat. It is indestructible and serves as a club or staff that does 4D6 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.73', NULL),
  ('athenas-spear', 'Athena''s Spear', 'rifts', 'weapon', NULL, NULL, NULL, '6D6+6 M.D.', 1, 'Thrown 2,000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'The holy spear of Athena, Greek goddess of war and wisdom; its metal head glows blue. It does 6D6+6 M.D., doubled against supernatural beings and creatures of magic (dragons included) and tripled against the Splugorth and vampire intelligences. It can remove a curse (70% chance) and, raised for all to see, turn 1D6x10 dead (85%). Thrown, it has a range of 2,000 feet (610 m) and returns to the wielder magically.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.75', NULL),
  ('athenas-holy-shield', 'Athena''s Holy Shield', 'rifts', 'armor', NULL, NULL, NULL, '2D4 M.D. (thrown)', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The shield of Athena, Greek goddess of war and wisdom: indestructible, yet as light as a feather. Its parry bonus is already counted in Athena''s own stats and is not printed separately. Thrown like a discus it does 2D4 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.75', NULL),
  ('athenas-magic-armor', 'Athena''s Magic Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 400, 'The magic armor of Athena, Greek goddess of war and wisdom. The book says only that it is lightweight and has 400 M.D.C.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.75', NULL),
  ('apollo-sun-bow', 'The Sun Bow', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, '4000 feet (1200 m)', NULL, NULL, NULL, NULL, NULL, 'Apollo''s bow, a greatest rune weapon with an I.Q. of 15 and scrupulous alignment that speaks by telepathy. It fires arrows of solar plasma that appear out of thin air: 2D6x10 M.D., tripled against vampires and alien intelligences, +4 to strike, range 4000 feet (1200 m). Bow and string are unbreakable, and three times a day it can cast each of invulnerability, impervious to energy, armor of Ithan and negate magic at the strength of a 15th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.76', NULL),
  ('aphrodite-golden-girdle', 'The Golden Girdle', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The girdle of Aphrodite, Greek goddess of love. While she wears it she can make any male in her line of sight fall in love with her: he must save vs magic (16 or higher) or become totally infatuated. It can be used up to three times per 24 hour period.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.77', NULL),
  ('hermes-winged-sandals', 'The Winged Sandals', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic sandals of Hermes, messenger of the Greek gods. They let him fly, run at 400 mph (640 km) on the ground or Mach 3 in the air, and travel between dimensions without error: running in a circle at top speed opens a mini-rift to another dimension. His stat block gives +6 additional to dodge when using them.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.78', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('hermes-winged-headband', 'The Winged Headband', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The headband of Hermes, messenger of the Greek gods. It gives an unerring sense of direction, senses the nearest rift or nexus, and senses where any god of Olympia (and only those) is, anywhere in the Megaverse. The book prints no figures for it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.78', NULL),
  ('hermes-herminator-rail-gun-pistol', 'The Herminator Rail Gun Pistol', 'rifts', 'weapon', 30, NULL, NULL, '1D4x10 M.D. per 10 round burst; 1D4 M.D. per single round', 1, '1000 feet (305 m)', '100 rounds', 'Standard', NULL, NULL, NULL, 'Hermes'' custom-built techno-wizard rail gun pistol, shaped like an old .44 Automag and firing BB-sized rounds (0.175 inch / 4.5 mm) of his own design at very high speed. It is so heavy that only a creature with supernatural strength of 20 or more, or a mortal with a P.S. of 30 or higher, can use it. A 10 round burst does 1D4x10 M.D. and one round 1D4 M.D.; range 1000 feet (305 m), payload 100 rounds, 30 lbs (13 kg).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.78', NULL),
  ('artemis-golden-bow', 'The Golden Bow', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The bow of Artemis, a rune weapon with an I.Q. of 13 that is telepathically linked to her. Its arrows do 2D6x10 M.D., double against vampires and supernatural intelligences, at +3 to strike. Artemis never carries fewer than 24 arrows, and her quiver sometimes holds Hephaestus'' arrows of slaying or cyclops-made lightning arrows (3D6x10 M.D.).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.80', NULL),
  ('ares-holy-sword', 'Ares'' Holy Sword', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The holy sword of Ares, Greek god of war. It does 1D6x10 M.D., doubled against vampires, intelligences and demons, and expels demons: 89% against lesser demons, 44% against greater demons.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.82', NULL),
  ('ares-golden-magic-plate-armor', 'Ares'' Golden Magic Plate Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 3000, 'A golden suit of magic plate armor made by Hephaestus for Ares, Greek god of war. It has 3,000 M.D.C. (1000 S.D.C. on S.D.C. worlds), repairs itself completely over a 24 hour period, and cannot be destroyed.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.82', NULL),
  ('dionysus-thyrsus', 'Thyrsus', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, 1000, 'The staff of Dionysus, Greek god of wine, cut from a Millennium Tree: 1000 M.D.C. and 120 P.P.E. It makes its wielder invulnerable to fire, and as a weapon does 6D6 M.D., doubled against supernatural creatures, but only in the hands of a demigod or greater being (otherwise normal damage). It casts each of repel animals, turn dead, circle of protection, remove curse and constrain being up to three times per 24 hours, as a 10th level sorcerer.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.83', NULL),
  ('hephaestus-invisible-net', 'Hephaestus'' Invisible Net', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 200, 'One of the weapons Hephaestus, smith of the Greek gods, has made: a super strong gladiator style net that only its wielder can see without magic or psionics. No ordinary weapon can cut it, and magic and mega-damage weapons do only one-quarter damage against its 200 M.D.C. A character with a P.S. of 40 or greater may be able to force it open and get out.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.84', NULL),
  ('hephaestus-chains-of-binding', 'Hephaestus'' Chains of Binding', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Chains and manacles made by Hephaestus, smith of the Greek gods; extremely rare. They look ordinary, but the chains cannot be broken and the manacles cannot be opened or picked: only the owner of the chains, or Hephaestus, can open and close them. The book prints no figures for them.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.84', NULL),
  ('hephaestus-arrows-of-slaying', 'Hephaestus'' Arrows of Slaying', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Magic hunting arrows made by Hephaestus, smith of the Greek gods, and used by Eros, Ares and many other gods of Olympia. They are +1 to strike, fly 25% farther than normal arrows and do 1D4x10 M.D. Eros usually has at least a dozen.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.84-85', NULL),
  ('eros-magic-bow-and-arrows', 'Eros'' Magic Bow and Arrows', 'rifts', 'weapon', NULL, NULL, NULL, NULL, 0, '6000 feet (1828 m)', NULL, NULL, NULL, NULL, NULL, 'The bow of Eros, Greek god of love: range 6000 feet (1828 m), firing mega-damage arrows or his love arrows (the book prints no damage for the bow itself). Eros makes up to four arrows per day of each type, and they lose potency over 48 hours. Pink arrows do no damage and make the victim amorous and outspoken about it; golden arrows make the victim fall in love with the first person of the appropriate sex seen; lead arrows remove all interest in another person and cancel a golden arrow. Each is defeated by a save vs magic of 18 or higher. He also usually carries six to 12 lightning arrows and four to eight love arrows.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.84-85', NULL),
  ('poseidons-trident', 'Poseidon''s Trident', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, 'Thrown 1000 ft (305 m)', NULL, NULL, NULL, NULL, NULL, 'The trident of Poseidon, Greek god of the sea: a rune weapon with an I.Q. of 16, telepathically linked to him. It does 2D6x10 M.D. and can be thrown 1000 ft (305 m). Three times per 24 hours it can cast each of impervious to energy, call lightning, calm storm and summon fog, as a 10th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.86', NULL),
  ('poseidon-sea-conch-of-storms', 'The Sea-Conch of Storms', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A magical wind instrument made from a large sea shell, owned by Poseidon, Greek god of the sea. It casts summon storm four times a day, equal to a 20th level warlock, at no P.P.E. cost to the user.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.86', NULL),
  ('triton-horn-of-the-ocean', 'Horn of the Ocean', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The horn of Triton, son and herald of Poseidon. It casts each of summon storm, calm storm, rain dance, tidal wave, creature of the waves, summon sharks/whales and part waters three times per 24 hour period, all equal to a 10th level warlock. Held to the ear, it lets the listener understand all languages.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.86', NULL),
  ('triton-sea-sword', 'Triton''s Sea Sword', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, 'Thrown 800 feet (244 m)', NULL, NULL, NULL, NULL, NULL, 'The sword of Triton, son and herald of Poseidon: three blades arranged in a trident shape. It does 1D6x10 M.D., can be thrown 800 feet (244 m) and magically returns to the thrower.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.86', NULL),
  ('hecate-living-armor-of-bone', 'Living Armor of Bone', 'rifts', 'armor', NULL, NULL, 'Lesser copies (half the M.D.C. and abilities) sell for 2D6x100 million credits; no price for the original', 'Stinger 6D6 M.D. plus venom 3D6 M.D. per melee for 1D6 melees; blades +3D6 M.D.; horn beam 1D6x10 M.D.', 1, 'Stinger 60 feet (18.3 m); horn beam 2000 feet (610 m)', NULL, NULL, NULL, NULL, 7000, 'The demonic-looking bio-wizard armor of Hecate, Greek goddess of magic: an amalgam of symbiotic creatures with 7,000 M.D.C. that regenerates 2D6x10 M.D.C. per minute and that she can teleport onto her body from any distance. A spine stinger whips out to 60 feet (18.3 m) for 6D6 M.D. plus venom (3D6 M.D. per melee for 1D6 melees; victims are -4 to strike, parry and dodge and at half speed); retractable blades add 3D6 M.D. to hand to hand attacks; the horns fire lightning for 1D6x10 M.D. at 2000 feet (610 m). A bio-field of 750 M.D.C. halves all energy damage. Her minions sell lesser copies, with half the M.D.C. and abilities, for 2D6x100 million credits.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.92', NULL),
  ('mamers-spear', 'Mamers'' Spear', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D.', 1, 'Thrown 1000 ft (305 m)', NULL, NULL, NULL, NULL, NULL, 'The spear of Mamers, the demon war god of Dark Olympus: a greatest rune weapon with all the basic abilities of one (those are in Rifts Atlantis, not printed here). It is a soul drinker and an animated, flying weapon that does 1D4x10 M.D. and can be thrown 1000 ft (305 m) and return to its owner.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.97', NULL),
  ('mamers-shield', 'Mamers'' Shield', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The indestructible magic shield of Mamers, the demon war god of Dark Olympus. It is +3 to parry and can parry energy blasts, but at -2.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.97', NULL),
  ('mamers-sword', 'Mamers'' Sword', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The short sword of Mamers, the demon war god of Dark Olympus: a rune weapon with the eight standard abilities. It does 6D6 M.D. and can parry energy blasts, but is at -2 to do so.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.97', NULL),
  ('cupid-bow-of-obsession', 'The Bow of Obsession', 'rifts', 'weapon', NULL, NULL, NULL, '2D6 M.D.', 1, '1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'The tiny golden bow of Cupid, the Terlin of Dark Olympus. It fires magical energy arrows of love or obsession, or magic fire arrows for self defense that do 2D6 M.D.; range 1000 feet (305 m). Cupid makes up to three love arrows per day of each type, and they lose potency over 48 hours. Arrows of romance do no damage and make the victim amorous; arrows of obsession make the victim irresistibly attracted to a person of Cupid''s choice for 2D4 weeks. Either is defeated by a save vs magic of 15 or higher, and remove curse cancels the obsession.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.97-98', NULL),
  ('mercury-enchanted-sword', 'Mercury''s Enchanted Sword', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The sword of Mercury the Messenger, the assassin of Dark Olympus and a fragment of the alien intelligence Jupiter. The book prints its damage alone: 4D6 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.98', NULL),
  ('zeus-the-thunderer-lightning-spear', 'Zeus the Thunderer''s Lightning Spear', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, 'Thrown 300 ft (91.5 m)', NULL, NULL, NULL, NULL, NULL, 'The lightning-shaped spear of Zeus the Thunderer, the dragon Trellacryth who leads the Olympian Club of impostors: a greater rune weapon. It does 1D6x10 M.D., double to vampires and alien intelligences, and can be thrown 300 ft (91.5 m) and return to the wielder. It casts four air elemental spells, up to four times a day in total, at 6th level: ball lightning (3D6+6 M.D., or an electrical field that does 9D6 M.D. to anyone touching it), call lightning (6D6 M.D.), darken the sky and whirlwind.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.103', NULL),
  ('athena-the-wise-techno-wizard-armor', 'Athena the Wise''s Techno-Wizard Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 320, 'The armor of Athena the Wise, the titan Melia Strongoak of the Olympian Club: extra-heavy composite armor with 320 M.D.C., too heavy for anything but a giant or a borg to carry. Its enchantments are usable three times a day: armor of Ithan (80 M.D.C.), impervious to energy and shadow meld.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.109', NULL),
  ('athena-the-wise-holy-sword', 'Athena the Wise''s Holy Sword', 'rifts', 'weapon', NULL, NULL, NULL, '4D6+6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The ancient sword of Athena the Wise, the titan Melia Strongoak of the Olympian Club, made by the god Thoth and her only inheritance from her parents. It does 4D6+6 M.D. and can expel devils and demons: 89% against lesser foes, 44% against greater demons.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.109', NULL),
  ('athena-the-wise-giant-laser-rifle', 'Athena the Wise''s Triax Style Giant Laser Rifle', 'rifts', 'weapon', NULL, NULL, NULL, '5D6 M.D. per blast', 1, '3000 feet (914 m)', '30 shot clip', NULL, NULL, NULL, NULL, 'The giant-sized, Triax style laser rifle of Athena the Wise, the titan Melia Strongoak of the Olympian Club. It does 5D6 M.D. per blast from a 30 shot clip at a range of 3000 feet (914 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.109', NULL),
  ('venus-the-adventurer-crown-of-venus', 'Crown of Venus', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The diadem of Venus the Adventurer, the elf Ylliriel Silverleaf of the Olympian Club: an ancient magic item that lets its wearer pass for a god. Its divine aura gives Horror Factor 10, makes her seem 10 levels of experience higher, is a 600 M.D.C. force field and gives +10 to save vs magic, psionics, disease and horror factor; it works three times per day, for three hours or until its M.D.C. is gone. A back-up force field of 60 M.D.C. can also be raised three times per day. Superhuman strength, superhuman speed, swim as a fish and fly as the eagle can each be used three times a day for 30 minutes.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.110', NULL),
  ('lord-hades-ppe-talisman', 'Lord Hades'' P.P.E. Talisman', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A talisman carried by Lord Hades, the temporal raider called Shell of the Olympian Club. It holds 100 P.P.E. for spell casting; the book prints nothing else about it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.111', NULL),
  ('lord-hades-heavy-combat-armor', 'Lord Hades'' Heavy Combat Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 120, 'The heavy combat armor of Lord Hades, the temporal raider called Shell of the Olympian Club: 120 M.D.C. It carries the spells armor of Ithan, impervious to energy and superhuman speed, all at 14th level spell strength.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.112', NULL),
  ('lord-hades-splugorth-armor-amulet', 'Lord Hades'' Splugorth Armor Amulet', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Splugorth item the Olympian Club took for itself, carried by Lord Hades, the temporal raider called Shell. It surrounds the wearer in a force field with 100 M.D.C. and can be activated three times a day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.112', NULL),
  ('varuna-lasso', 'Varuna''s Lasso', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic noose Varuna, the deposed head of the Vedic gods, carries to capture evil beings. It gives its user +3 to strike and ensnare. An ensnared character needs a P.S. of 60 or higher, or a natural 20, to get free, and is -5 to strike, parry and dodge; one securely bound is -10 and at half speed.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.114', NULL),
  ('vajra-the-thunderbolt', 'Vajra, the Thunderbolt', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, 'Thrown: 1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'Indra''s rune weapon. It does double damage to evil beings and the undead, and can change shape into a scepter/mace or a discus that is thrown 1000 feet (305 m) and returns to its wielder. Up to three times per 24 hours each it casts calm storms, summon fog, summon rain, and summon and control storm, all as 10th level spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('indra-lightning-javelins', 'Indra''s Lightning Javelins', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, '2,000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'Thin silver wands carried by Indra, god of storms, that turn into lightning bolts when thrown. Each does 2D6x10 M.D. at a range of 2,000 feet (610 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('indra-twin-daggers', 'Indra''s Twin Daggers', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Two curved kris daggers, lesser rune weapons with identical powers, carried by Indra. Each is a soul drinker, inflicts 2D4x10 M.D., and can parry lightning bolts on a normal parry roll.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('soma-potion', 'Soma Potion', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic liquid Indra drinks, which only the gods Soma and Tvashtri know how to make; Indra usually carries 1D6x10 doses. A dose raises P.S. to 60 (70 if it was already 40 or more), adds 2,000 M.D.C. (or turns an S.D.C. being into a 2,000 M.D.C. creature), adds 1,000 P.P.E. and 400 I.S.P., and gives +1 to strike, parry or dodge and +2 to save vs horror factor, all for 1D6x10 minutes (twice as long for humans). When it ends the drinker is weak for one hour: -20 to P.S., M.D.C./S.D.C. halved, and -2 to strike, parry and dodge. It is addictive: without a dose at least once a week the weakness becomes permanent until another dose or 3D4 months of detox and withdrawal.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('indra-plasma-rifle', 'Indra''s Plasma Rifle', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D. per blast', 1, '3000 feet (914 m)', '24 blasts; regenerates one blast charge per hour', NULL, NULL, NULL, 100, 'An alien weapon that fires plasma bolts, carried by Indra. The rifle has 100 M.D.C., does 1D4x10 M.D. per blast to 3000 feet (914 m), and holds 24 blasts, regaining one charge per hour.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('indra-flying-disc', 'Indra''s Flying Disc', 'rifts', 'vehicle', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'An alien anti-gravity platform Indra rides when he is not on his elephant. It has 1000 M.D.C., flies at Mach 8, can make pin-point stops and maneuvers, and is completely silent. It carries no weapon systems.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.115', NULL),
  ('tvashtri-shifter', 'The Shifter', 'rifts', 'weapon', NULL, NULL, NULL, '1D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A small golden wand, the one-of-a-kind masterwork of Tvashtri, god of magic and rune smith of the Vedic gods. It is indestructible and is only a 1D6 M.D. blunt weapon in any hands but his. Attuned to Tvashtri alone, it holds FIVE greatest rune weapons that he can call out one at a time (the five are described in Rifts Atlantis, not here); he can switch as often as once per melee round, and a weapon summoned and dismissed cannot be summoned again for 24 hours.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.116', NULL),
  ('surya-sun-staff', 'Surya''s Sun Staff', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The golden rune staff of Surya the sun god, with an orb at one end that shines as a globe of daylight unless he wills otherwise. It has an I.Q. of 11, a telepathic link with him and a principled alignment: a creature of evil or selfish alignment that touches it is burned for 1D4x10 M.D. It inflicts 6D6 M.D., triple against vampires and undead, and three times per 24 hours casts blinding flash, swirling lights, circle of flame, fire ball and wall of flame as a 10th level fire warlock.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.119', NULL),
  ('ratri-shadowblade', 'The Shadowblade', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The jet black rune sword of Ratri, goddess of shadows, made of elemental shadow stuff bound with runes. It has an I.Q. of 10, a telepathic link to her, is indestructible and of scrupulous alignment: a creature of evil alignment that touches it is burned for 1D4x10 M.D. It does 2D4x10 M.D., doubled against creatures of the night such as vampires and djinns, and three times per 24 hours casts globe of daylight, negate magic, anti-magic cloud, remove curse and extinguish flames as a 10th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.120', NULL),
  ('brahma-scepter', 'Scepter of Brahma', 'rifts', 'weapon', NULL, NULL, NULL, '3D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Brahma''s greatest rune weapon, with an I.Q. of 13 and a telepathic link to him. It inflicts 3D4x10 M.D., double against vampires and alien intelligences. Three times per 24 hours it casts the water spells cloud of steam, salt water to fresh, dowsing, fog of fear, ride the waves, walk the waves, calm waters, hail and wall of ice, and the spells invulnerability, armor of Ithan, impervious to energy and energy field, all as 10th level spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.123', NULL),
  ('brahma-heavenly-bow', 'Brahma''s Heavenly Bow', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, '2000 feet (610 m)', 'Anti-undead arrows: 24 per day', NULL, NULL, NULL, NULL, 'Brahma''s indestructible black rune bow, which makes its own arrows as it is drawn. Red energy arrows do 2D6x10 M.D. to 2000 feet (610 m), each shot one melee attack. Black curse arrows deliver luck curse, minor curse, phobia curse, compulsion or remove curse (64%) at his choice, each three times per 24 hours as a 10th level spell. White anti-undead arrows seek a vampire''s heart, become a wooden shaft that paralyzes it and burn it up the next round; range 2000 ft (610 m), and only 24 can be made per day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.123', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('brahma-beads-of-power', 'Brahma''s Beads of Power', 'rifts', 'magic', NULL, NULL, NULL, 'Beads of Destruction: 1D6x10 M.D. to a 20 foot (6 m) radius', 1, 'Thrown: 200 ft (61 m; 5 times farther if thrown by Brahma)', NULL, NULL, NULL, NULL, NULL, 'A string of 12 magic beads belonging to Brahma; a used bead comes back 24 hours later, and one granted to a follower works once and returns to him. Three Beads of Energy hold 300 P.P.E. each. Three Beads of Destruction are thrown 200 ft (61 m; five times farther by Brahma) and explode for 1D6x10 M.D. in a 20 foot (6 m) radius. Three Beads of Protection, crushed in the hand, give armor of Ithan at 20th level (200 M.D.C.), and three Beads of Negation, thrown to the ground, make an anti-magic cloud as a 20th level spell.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.123', NULL),
  ('brahma-sacred-book-of-knowledge', 'Brahma''s Sacred Book of Knowledge', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The tome Brahma never lets out of his sight, holding hundreds of spell and circle invocations. By reading the passage, which takes one full melee round, he can cast any spell he does not know, including elemental, temporal and necromantic magic, at the highest level of the caster''s experience. It works like a book of permanent scrolls: reading does not teach the spell, and the book holds no rune magic or bio-wizardry.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.123', NULL),
  ('sudarsana-the-discus', 'Sudarsana the Discus', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, 'Thrown: 1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'Vishnu''s saucer-shaped greatest rune weapon, indestructible, with an I.Q. of 16, a telepathic link to him and a scrupulous alignment: an evil being that touches it is burned for 1D4x10 M.D. It inflicts 2D6x10 M.D., doubled against beings of evil alignment, and can be thrown 1000 feet (305 m), returning to the wielder. If it hits someone attempting to teleport, the attempt fails and the victim is at -50% on further attempts that day.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.124', NULL),
  ('panchajanya-the-shell', 'Panchajanya the Shell', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Vishnu''s magic shell, which once housed a demon. Its energy field adds +2 to dodge, and it can raise an energy bubble shield of 500 M.D.C. covering a 20 foot (6 m) radius, usually used to protect others.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.124', NULL),
  ('kaunodaki-the-mace', 'Kaunodaki the Mace', 'rifts', 'weapon', NULL, NULL, NULL, '4D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Vishnu''s mace, a greatest rune weapon often carried by his avatar Krishna. It is indestructible, has an I.Q. of 11, links telepathically to its wielder and is of principled alignment: a being of any evil alignment that touches it is burned for 1D6x10 M.D. It does 4D4x10 M.D., tripled against dragons and vampire intelligences, and three times a day each casts transferal, banishment, mystic portal and time hole at 12th level spell strength.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.124', NULL),
  ('sarnga-the-magic-bow', 'Sarnga, the Magic Bow', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, '4000 feet (1200 m)', NULL, NULL, NULL, NULL, NULL, 'Vishnu''s magic bow. It has a range of 4000 feet (1200 m) and fires magic energy arrows that do 2D6x10 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.124', NULL),
  ('pinaka-siva-trident', 'Pinaka, Siva''s Trident', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The rune trident of Siva the Destroyer, with an I.Q. of 10 and a telepathic link to him. It is of aberrant alignment and usable only by aberrant and principled characters: a miscreant, diabolic, selfish or scrupulous character who touches it is burned for 1D4x10 M.D. It inflicts 2D4x10 M.D., triple against alien intelligences and double against demons and vampires. Three times per 24 hours each it casts circle of rain, hail, hurricane, rain dance and summon storm, and thunder clap, stop wind, change wind direction, call lightning and calm storm, all as 10th level spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.127', NULL),
  ('ajagawa-siva-bow', 'Ajagawa, Siva''s Bow', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, '4000 feet (1200 m)', NULL, NULL, NULL, NULL, NULL, 'Siva''s bow, with a range of 4000 feet (1200 m), firing magic arrows that do 1D6x10 M.D. It needs a P.S. of at least 30 to draw and is +2 to strike.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.127', NULL),
  ('khatwanga-the-mace', 'Khatwanga the Mace', 'rifts', 'weapon', NULL, NULL, NULL, '3D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Siva''s magical mace, shaped as a garuda, the heavy Hindu mace. Its only power is the damage it does: 3D6x10 M.D.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.127', NULL),
  ('sashonu-parvati-magic-sword', 'Sashonu, Parvati''s Magic Sword', 'rifts', 'weapon', NULL, NULL, NULL, '3D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The magic sword of Parvati, Siva''s wife. It does 3D4x10 M.D., doubled against demons, and three times a day each casts magic net, wisps of confusion and energy field as 8th level spells. It can fashion ten replicas of itself, one for each of her arms; a replica inflicts 1D4x10 M.D. and has no spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.128', NULL),
  ('skanda-enchanted-scale-mail-armor', 'Skanda''s Enchanted Scale Mail Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'The golden scale armor of Skanda, the Hindu god of war. It has 2,000 M.D.C., is as light as a feather and makes no noise.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.129', NULL),
  ('skanda-giant-plasma-sword', 'Skanda''s Giant Plasma Sword', 'rifts', 'weapon', NULL, NULL, NULL, 'Adds 1D4x10 M.D. to P.S. damage', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'A giant plasma sword carried by Skanda, the Hindu god of war. It adds 1D4x10 M.D. to the wielder''s P.S. damage; the book prints nothing else for it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.129', NULL),
  ('skanda-plasma-cannon', 'Skanda''s Plasma Cannon', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D.', 1, '3000 feet (915 m)', '30 shots; regenerates 5 an hour', NULL, NULL, NULL, NULL, 'The plasma cannon carried by Skanda, the Hindu god of war. It does 1D4x10 M.D. to 3000 feet (915 m) and holds 30 shots, regaining 5 an hour.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.129', NULL),
  ('skanda-techno-wizard-war-helmet', 'Skanda''s Techno-Wizard War Helmet', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The horned techno-wizard helmet of Skanda, the Hindu god of war. It makes the wearer impervious to possession and mind control, lets him see the invisible and see in infrared and ultraviolet light, and has radar tracking with a HUD display that follows up to 72 targets to 20 miles (32 km). It also gives +1 to strike.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.129', NULL),
  ('ganesa-club', 'Ganesa''s Club', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, 'Thrown: 1,000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'A greater rune weapon given to the elephant god Ganesa by his father Siva. It inflicts 2D4x10 M.D. and can be thrown 1,000 feet (305 m), returning to its wielder. Three times per day it casts invulnerability, globe of silence, invisibility: superior, negate magic and stone to flesh as a 10th level magic practitioner.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.130', NULL),
  ('ganesa-discus', 'Ganesa''s Discus', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, '2000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'A magical throwing weapon carried by the elephant god Ganesa. It inflicts 1D6x10 M.D. at a range of 2000 feet (610 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.130', NULL),
  ('kali-demonblade', 'The Demonblade', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, 'Demonfire: 1000 ft (305 m)', NULL, NULL, NULL, NULL, 10000, 'Kali''s sword, made by twisting a demon lord''s body and binding its spirit into a blade. It has an I.Q. of 20, a telepathic link to her and an evil alignment: a being of good or selfish alignment that touches it is burned for 1D6x10 M.D. Not quite indestructible, it has 10,000 M.D.C. (hit only by a called shot at -2), regenerates 1D6x100 M.D.C. per minute and takes half damage from energy. It does 2D6x10 M.D., doubled against good beings, or fires a 2D6x10 M.D. demonfire blast to 1000 ft (305 m) whose pain puts the victim at -2 on all actions for one melee round. Three times per day it wraps its wielder in a flame aura of 200 M.D.C. lasting 4 hours: no damage from fire, half from all energy attacks.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.134', NULL),
  ('kali-demon-head', 'Kali''s Demon''s Head', 'rifts', 'magic', NULL, NULL, NULL, 'Bite: 3D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, 1000, 'The severed head of a demon lord, preserved by necromantic magic and carried by Kali. It is immune to all non-magical attacks, has 1000 M.D.C. and regenerates 1D4x100 M.D.C. per minute, and has an I.Q. of 24 with a telepathic link to her. It casts agony, befuddle, domination, fire ball, mute and fear at will as a 10th level ley line walker from 200 P.P.E., regaining 20 P.P.E. every hour. Its bite does 3D6 M.D. and holds on, leaving the victim -2 to parry and dodge until he breaks free with a P.S. of 20; it can speak, but only to lie.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.134', NULL),
  ('yama-great-mace', 'Yama''s Great Mace', 'rifts', 'weapon', NULL, NULL, NULL, '3D4x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'The magical mace of Yama, the Hindu god of death. It inflicts 3D4x10 M.D.; the book prints no other power.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.136', NULL),
  ('noose-of-yama', 'The Noose of Yama', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The enchanted noose Yama, the Hindu god of death, uses to capture enemies. It is +3 to strike, and on a successful undefended hit binds the target completely in one full melee round, leaving him able to act only by psionics or magic. Breaking free by brute force takes a P.S. of 45; a successful dodge or save vs magic, 16 or higher for both, evades it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.136', NULL),
  ('odin-enchanted-chain-mail', 'Odin''s Enchanted Chain Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'The lightweight enchanted chain mail Odin wears into combat. It provides 2,000 M.D.C. The page prints no other property.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.148', NULL),
  ('gungnir', 'Gungnir', 'rifts', 'weapon', NULL, NULL, NULL, '3D6x10 M.D.', 1, 'Thrown 1000 ft (305 m)', NULL, NULL, NULL, NULL, NULL, 'Odin''s golden spear, a greatest rune weapon that needs a P.S. of 24 to use. It has I.Q. 10 and a telepathic link with Odin, is indestructible and of selfish alignment (a creature of evil alignment that touches it suffers 3D6 damage), can be thrown 1000 ft (305 m) and returns, and does 3D6x10 M.D. thrown or in hand: double to vampires, undead and supernatural intelligences (not gods), triple to supernatural and Norse giants. Once per melee round a True Strike throw cannot be avoided, hits the main body for normal damage and counts as two melee attacks. As a weapon breaker, a called shot at -3 to strike shatters the enemy''s weapon unless it saves vs magic at 16 or greater or the blow is dodged (it cannot be parried); Techno-Wizard, magic and holy weapons are +2 to that save and lesser rune weapons +6, while greater and greatest rune weapons cannot be destroyed but may be knocked from the hand. Its user can cast teleport: lesser, teleport: greater, mystic portal, time hole and sanctum two times each per 24 hours, as 10th level spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.148', NULL),
  ('draupnir', 'Draupnir', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Odin''s ring, a plain golden band. The wearer is +2 to save vs magic and +2 to resist Horror Factor, and is protected as if by Mind Block Auto-Defense. At Odin''s command it makes nine identical copies of itself every ninth night; the copies carry the same powers and bonuses but cannot duplicate themselves, and were given to loyal followers as rewards.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.148', NULL),
  ('tyr-silver-spear', 'Tyr''s Silver Spear', 'rifts', 'weapon', NULL, NULL, NULL, '2D6x10 M.D.', 1, 'Thrown 1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'A greater rune weapon carried by Tyr, a gift from Odin and the Norse Dwarves. It has I.Q. 12; the page prints its telepathic link as being to Heimdall, although the spear is listed in Tyr''s own equipment. It does 2D6x10 M.D., can be thrown 1000 feet (305 m) and returns to its owner. It casts invulnerability, fire ball, impervious to energy, call lightning, minor curse and mystic portal three times each per day as an 11th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.149', NULL),
  ('tyr-axe-of-justice', 'Tyr''s Axe of Justice', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, 'Thrown 500 feet (152 m)', NULL, NULL, NULL, NULL, NULL, 'Tyr''s indestructible magic axe. It inflicts 6D6 M.D. and returns when thrown, with a range of 500 feet (152 m).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.149', NULL),
  ('thor-magic-chain-mail', 'Thor''s Magic Chain Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'Thor''s lightweight magic chain mail, providing 1000 M.D.C. The page prints no other property.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.150', NULL),
  ('mjolnir', 'Mjolnir', 'rifts', 'weapon', NULL, NULL, NULL, '4D6x10 M.D.', 1, 'Thrown 2000 ft (610 m)', NULL, NULL, NULL, NULL, NULL, 'Thor''s short-handled war-hammer, the greatest rune weapon the Norse Dwarves made, indestructible and a holy symbol that repels the undead. It does 4D6x10 M.D. thrown or in hand (+55 with the Belt of Might), double to giant races, gargoyles, supernatural predators and demons, dragons and alien intelligences, with a throwing range of 2000 ft (610 m), and flies back to Thor''s hand. Four times a day a throw strikes automatically (no parry or dodge) for normal damage. It can call lightning at will, as often as once per melee round and counting as one attack, for 2D6x10 M.D. at 1000 ft (305 m), and can shrink to the size of a small amulet. Returning from a throw it does 2D6 M.D. to the wielder''s hand or armor unless the magic gloves are worn.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.150', NULL),
  ('megingiord', 'Megingiord, Thor''s Belt of Might', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Thor''s golden belt. On Thor it raises his strength to P.S. 70 and turns his normal S.D.C. P.S. damage bonus into mega-damage (his stat block gives +55 M.D. with the belt). Anyone else who wears it has the P.S. attribute doubled, to a maximum of 60, and that strength counts as supernatural; the mega-damage bonus applies only to Thor.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.150', NULL),
  ('iarn-greiper', 'Iarn Greiper, Thor''s Iron Gloves', 'rifts', 'magic', NULL, NULL, NULL, '2D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Thor''s magic iron gloves, which let him catch Mjolnir without burning his hands. A squeeze or crush with the gloved hands does 2D6x10 M.D. The wearer can also hold rune weapons of opposing alignment without taking damage, though a character of conflicting alignment still cannot use such a weapon''s magic or bonuses.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.150-152', NULL),
  ('heimdall-enchanted-chain-mail', 'Heimdall''s Enchanted Chain Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'Heimdall''s enchanted chain mail: 1000 M.D.C., lightweight, silent, and impervious to fire and cold.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.154', NULL),
  ('heimdall-sword', 'Heimdall''s Sword', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Heimdall''s greater rune broadsword, red-bladed and covered in runes. It is indestructible, has I.Q. 12 and is of scrupulous alignment. It inflicts 1D6x10 M.D., double against supernatural monsters, giants, dragons and vampires. It casts impervious to energy, invulnerability, constrain being, dispel magical barriers, negate magic, call lightning and fire ball three times each per 24 hours as a 10th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.154', NULL),
  ('loki-sword-of-atlantis', 'Loki''s Sword of Atlantis', 'rifts', 'weapon', NULL, NULL, NULL, 'Fire blast 1D6x10 M.D., force blast 2D4x10 M.D., lightning blast 1D6x10 M.D.', 1, 'Fire and force blasts 1000 feet (305 m); lightning blast 2000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'A rune sword Loki swindled from a Splugorth. It has I.Q. 15 and a telepathic link to Loki, and is of evil alignment: a creature of good alignment that touches it is burnt for 1D4x10 M.D. It grants teleport: lesser, teleport: greater, mystic portal, time hole and sanctum three times each per 24 hours as 10th level spells. Its double dragon heads breathe one blast type at a time, each a melee action: fire 1D6x10 M.D. to 1000 feet (305 m), force 2D4x10 M.D. to 1000 feet (305 m) or lightning 1D6x10 M.D. to 2000 feet (610 m), all double to vampires and alien intelligences. The page prints no damage for the blade itself.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.155-156', NULL),
  ('balder-earth-blade', 'Balder''s Earth Blade', 'rifts', 'weapon', NULL, NULL, NULL, '4D6+6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Balder''s greatest holy weapon, a blade that glows faint white. It does 4D6+6 M.D., triple to targets of evil alignment. It has a 50% chance to remove a curse, expels devils and demons (89% against lesser demons, 44% against greater), and raised overhead and struck on the ground makes a circle of protection like the lesser spell, lasting five minutes per level of the wielder (75 minutes for Balder).', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.157', NULL),
  ('njord-sea-spear', 'Njord''s Sea Spear', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, 'Thrown 1000 ft', NULL, NULL, NULL, NULL, NULL, 'Njord''s magical spear. It inflicts 2D4x10 M.D., can be thrown underwater as well as over dry ground to a range of 1000 ft, and returns to the wielder''s hand.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.159', NULL),
  ('brisingamen', 'The Brisingamen', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Freya''s ancient golden necklace, which only she can activate. Its aura of fertility makes everything and everybody within 10 miles more fertile or productive for as long as she wills it: crops grow a month''s worth in a week and farmers and their beasts work twice as hard. While she wears it Freya has +4 to all rolls to save, pull punch, dodge and called shots.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.161', NULL),
  ('hrungnir-magical-chain-mail', 'Hrungnir''s Magical Chain Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1000, 'The grey magical chain mail of the giant Hrungnir, with 1000 M.D.C. The page prints no other property.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.164', NULL),
  ('hrungnir-whetstone', 'Hrungnir''s Whetstone', 'rifts', 'weapon', NULL, NULL, NULL, '4D6x10 M.D.', 1, 'Thrown 1000 ft (305 m)', NULL, NULL, NULL, NULL, 1000, 'The giant Hrungnir''s magical stone hammer. It needs a P.S. of 30, and a being under 12 feet (3.6 m) tall is -2 to hit with it. It is not indestructible: it has 1,000 M.D.C. and regenerates 1D4x100 M.D.C. per minute. It does 4D6x10 M.D. and can be thrown 1000 ft (305 m), returning to the wielder.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.164', NULL),
  ('hrungnir-stone-shield', 'Hrungnir''s Stone Shield', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 3000, 'The giant Hrungnir''s enchanted slab of stone. It has 3,000 M.D.C. and regenerates 1D6x10 M.D.C. per minute, gives +3 to parry, can parry missiles and energy weapons at no penalty, and gives +4 to save vs spells.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.164', NULL),
  ('thorg-dragon-thunderer-hammer', 'Thorg''s Dragon Thunderer Hammer', 'rifts', 'weapon', NULL, NULL, NULL, '1D4x10 M.D.', 1, 'Thrown 300 feet (91.5 m)', NULL, NULL, NULL, NULL, NULL, 'The greatest rune weapon of Thorg the Mighty, the Kydian powerlord who passes for Thor. It is indestructible, of anarchist alignment, with I.Q. 10. It does 1D4x10 M.D. and releases a thunderclap whenever it strikes, can be thrown 300 feet (91.5 m) and returns after it strikes. It casts invulnerability, levitation, summon rain and calm storms three times each per 24 hours as an 8th level sorcerer.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.171-172', NULL),
  ('alattreen-techno-wizard-hammer', 'A''Lattreen''s Techno-Wizard Hammer', 'rifts', 'weapon', NULL, NULL, NULL, '6D6 M.D.', 1, 'Thrown 100 feet (30.5 m)', NULL, NULL, NULL, NULL, NULL, 'The Techno-Wizard hammer of A''Lattreen, the Sowki who poses as Thor the Warrior. It is surrounded by an energy field and inflicts 6D6 M.D. when powered up. It can be thrown 100 feet (30.5 m) and returns to him through a psionic remote control system.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.176', NULL);

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('ahura-mazda-sword-of-truth', 'Ahura Mazda''s Sword of Truth', 'rifts', 'weapon', NULL, NULL, NULL, '4D6 M.D. to mortals, 1D6x10 to demons, 1D6x100 to gods and alien intelligences', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Ahura Mazda''s greatest rune weapon, whose only power is its damage: 4D6 M.D. to mortals, 1D6x10 to demons and 1D6x100 to gods and alien intelligences. It has an I.Q. of 14 and is indestructible.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.181', NULL),
  ('ahura-mazda-robe-of-stars', 'Ahura Mazda''s Robe of Stars', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 4000, 'Ahura Mazda''s enchanted black robe with a starry pattern. It provides 4000 M.D.C. Mortals and demigods can walk into the robe and be teleported or dimensionally teleported home, or to any destination the god chooses.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.181', NULL),
  ('asha-magic-plate-mail', 'Asha''s Magic Plate Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'The golden magic plate mail Asha wears in combat, with 2000 M.D.C. The page prints no other property.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.182', NULL),
  ('asha-holy-sword', 'Asha''s Holy Sword', 'rifts', 'weapon', NULL, NULL, NULL, '6D6+6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Asha''s golden blade, which glows a faint red. It does 6D6+6 M.D., double against beings of diabolic alignment. Raised overhead it turns 4D6 dead with an 80% chance; its healing touch restores 2D6 S.D.C. and hit points, or 2D6 M.D.C.; and it expels devils and demons, 89% against lesser foes and 44% against greater demons.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.182', NULL),
  ('vohu-manah-scepter-of-magic', 'Vohu Manah''s Scepter of Magic', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Vohu Manah''s greatest rune weapon, a golden rod with a star-shaped head held in an eagle''s claw. It has I.Q. 15 and a telepathic link to Vohu Manah. It casts negate magic, remove curse, speed of the snail, anti-magic cloud and impenetrable wall of force up to three times each per 24 hours, all as 10th level spells, and does 1D6x10 M.D. when used as a weapon.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.183', NULL),
  ('vohu-manah-diadem-of-knowledge', 'Vohu Manah''s Diadem of Knowledge', 'rifts', 'magic', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Vohu Manah''s diamond-encrusted headband. Three times per day the wearer can perform any skill at 98%, known or not. It also lets him read runes and mystic symbols, identify wards and circles and recognize enchantments, all at 88%, and cast a spell at 20th level of potency four times per 24 hours.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.183', NULL),
  ('sharevar-enchanted-plate-mail', 'Sharevar''s Enchanted Plate Mail Armor', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'Sharevar''s enchanted plate mail: 2000 M.D.C., light weight, and it regenerates 1D4x100 M.D.C. per hour.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.185', NULL),
  ('sharevar-spear-of-justice', 'Sharevar''s Spear of Justice', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.; 2D4x100 to Ahriman and supernatural intelligences', 1, 'Thrown 2,000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'Sharevar''s greatest rune weapon, a red spear with a wide-blade point. It has I.Q. 13 and a telepathic link to Sharevar. It does 2D4x10 M.D. to most enemies but 2D4x100 to Ahriman and supernatural intelligences, can be thrown 2,000 feet (610 m) and returns to its owner. It casts call lightning, energy field, dispel magical barrier and negate magic three times each per 24 hours as a 10th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.185', NULL),
  ('sharevar-shield', 'Sharevar''s Shield', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Sharevar''s indestructible shield. It gives him +3 to parry and can parry energy beams, but at -2. The page prints no M.D.C. for it.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.185', NULL),
  ('verethraghna-enchanted-plate-mail', 'Verethraghna''s Enchanted Plate Mail', 'rifts', 'armor', NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 2000, 'Verethraghna''s enchanted plate mail, with 2000 M.D.C. The page prints no other property.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.188', NULL),
  ('verethraghna-golden-blade', 'Verethraghna''s Golden Blade', 'rifts', 'weapon', NULL, NULL, NULL, '3D4x10 M.D.; fire blast 1D6x10 M.D., force blast 2D4x10 M.D., lightning blast 1D6x10 M.D.', 1, 'Fire and force blasts 1000 feet (305 m); lightning blast 2000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'Verethraghna''s greater rune weapon, an ornate sword whose pommel is two intertwined dragons with ruby eyes. It has I.Q. 11 and a telepathic link to Verethraghna and does 3D4x10 M.D. The double dragon heads breathe one blast at a time down the blade: fire 1D6x10 M.D. to 1000 feet (305 m), force 2D4x10 M.D. to 1000 feet (305 m) or lightning 1D6x10 M.D. to 2000 feet (610 m), all double to supernatural monsters.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.188', NULL),
  ('vayu-spear-of-the-wind', 'Vayu''s Spear of the Wind', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, 'Thrown 2,000 feet (610 m)', NULL, NULL, NULL, NULL, NULL, 'Vayu''s enchanted spear. It inflicts 1D6x10 M.D., can be thrown 2,000 feet (610 m) and returns to the wielder. It also talks, offering comments and suggestions.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.189', NULL),
  ('vayu-sword-of-lightning', 'Vayu''s Sword of Lightning', 'rifts', 'weapon', NULL, NULL, NULL, '1D6x10 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Vayu''s two-handed greatest rune weapon, golden in blade and hilt with a lightning motif. It has I.Q. 12 and a telepathic link to Vayu, has healing abilities (the page gives no figures for them), and does 1D6x10 M.D. It casts call lightning, remove curse, oracle and animate/control dead three times each per 24 hours as a 9th level spell caster.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.189', NULL),
  ('ahriman-sword-of-hatred', 'Ahriman''s Sword of Hatred', 'rifts', 'weapon', NULL, NULL, NULL, '3D6x10 M.D.', 1, 'Thrown 1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'Ahriman''s jet black two-handed rune sword with red runes and a bat-wing pommel that lets it float and fight alone. It has I.Q. 16 and a telepathic link to Ahriman and is of diabolic alignment: anyone of good or anarchist alignment takes 6D6 damage every round the blade is held. It can be thrown 1000 feet (305 m) and flies back, and can fight by itself up to 200 feet (61 m) from its owner at +4 to strike and parry and +2 to initiative. It inflicts 3D6x10 M.D., doubled against creatures of magic including dragons, alien intelligences, faeries and Gods of Light. It casts invulnerability, levitation, compulsion, dominance and fear up to three times each per 24 hours, but not while fighting by itself.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.195', NULL),
  ('aeshma-dragon-thunderer-axe', 'Aeshma''s Dragon Thunderer Axe', 'rifts', 'weapon', NULL, NULL, NULL, '2D4x10 M.D.', 1, 'Thrown 1000 feet (305 m)', NULL, NULL, NULL, NULL, NULL, 'Aeshma''s red dragon-headed axe, a more powerful version of the Dragon Thunderer of Rifts Atlantis. It has I.Q. 10 and a telepathic link to Aeshma and is of diabolic alignment: a creature of good or anarchist alignment that touches it is burnt for 5D6 M.D. every round it is held. It does 2D4x10 M.D. with a thunderclap whenever it strikes, has a throwing range of 1000 feet (305 m) and returns after it strikes. It casts invulnerability, levitation, summon rain and calm storms as often as six times each per 24 hours as a 10th level sorcerer.', 'Rifts Conversion Book Two: Pantheons of the Megaverse p.197', NULL);

